import datetime as dt

from django.utils import timezone

# A cheque received within this many days before the migration goes to the portfolio for the office to follow;
# an older one is taken as cashed (D-196).
RECENT_CHEQUE_DAYS = 30


def add_lines(apps, schema_editor):
    """Every payment recorded before D-196 gets its one line; a cheque gets its effet in the treasury, bank empty
    ("à compléter"): in portfolio when recent, taken as cashed when older, cancelled when the payment was voided."""
    CustomerPayment = apps.get_model("sales", "CustomerPayment")
    CustomerPaymentLine = apps.get_model("sales", "CustomerPaymentLine")
    Instrument = apps.get_model("treasury", "Instrument")
    InstrumentEvent = apps.get_model("treasury", "InstrumentEvent")
    recent = timezone.localdate() - dt.timedelta(days=RECENT_CHEQUE_DAYS)
    for payment in CustomerPayment.objects.select_related("customer").order_by("id").iterator():
        instrument = None
        reference = payment.reference
        if payment.method == "cheque":
            if payment.voided_at is not None:
                status = "cancelled"
            elif payment.received_on >= recent:
                status = "portfolio"
            else:
                status = "cashed"
            instrument = Instrument.objects.create(
                organization_id=payment.organization_id,
                direction="received",
                kind="cheque",
                number=(payment.reference or payment.number)[:50],
                drawer=payment.customer.name[:150],
                amount=payment.amount,
                issued_on=payment.received_on,
                due_on=payment.received_on,
                status=status,
                customer_id=payment.customer_id,
                source_number=payment.number,
                notes="Repris d'un règlement d'avant la trésorerie : banque et échéance à compléter.",
                created_by_id=payment.created_by_id,
            )
            InstrumentEvent.objects.create(
                organization_id=payment.organization_id,
                instrument=instrument,
                to_status="portfolio",
                happened_on=payment.received_on,
            )
            if status != "portfolio":
                InstrumentEvent.objects.create(
                    organization_id=payment.organization_id,
                    instrument=instrument,
                    from_status="portfolio",
                    to_status=status,
                    happened_on=timezone.localdate(),
                    note="Repris : supposé encaissé." if status == "cashed" else "Règlement annulé.",
                )
            reference = ""
        CustomerPaymentLine.objects.create(
            organization_id=payment.organization_id,
            payment=payment,
            method=payment.method,
            amount=payment.amount,
            reference=reference,
            instrument=instrument,
        )



